mapper.select:
SELECT COUNT(*) FROM game_tournament t
  JOIN game_tournament_player p1 ON p1.tournament_id = t.id
  JOIN game_tournament_player p2 ON p2.tournament_id = t.id
 WHERE t.kind = 'DUEL'
   AND t.status IN ('INVITING', 'RUNNING')
   AND t.deleted_at IS NULL
   AND t.game_id = #{gameId}
   AND p1.user_id = #{firstUserId}
   AND p2.user_id = #{secondUserId}

SELECT * FROM game_tournament_player
 WHERE tournament_id = #{tournamentId}
 ORDER BY seed ASC, invited_at ASC

mapper.update:
UPDATE game_tournament_player
   SET status = 'ACCEPTED', nickname = #{nickname}, responded_at = #{now}
 WHERE tournament_id = #{tournamentId} AND user_id = #{userId} AND status = 'INVITED'

UPDATE game_tournament_player
   SET status = 'DECLINED', responded_at = #{now}
 WHERE tournament_id = #{tournamentId} AND user_id = #{userId} AND status = 'INVITED'

UPDATE game_tournament_player
   SET status = 'DECLINED', responded_at = #{now}
 WHERE tournament_id = #{tournamentId} AND status = 'INVITED'

UPDATE game_tournament
   SET current_round = #{nextRound}
 WHERE id = #{tournamentId} AND status = 'RUNNING' AND current_round = #{expectedRound}

UPDATE game_tournament
   SET bracket_type = 'PAGE_PLAYOFF', total_rounds = #{totalRounds}, current_round = #{firstRound}
 WHERE id = #{tournamentId} AND status = 'RUNNING'
   AND bracket_type = 'LEAGUE' AND current_round = #{expectedRound}

UPDATE game_tournament
   SET bracket_type = 'LADDER', total_rounds = #{totalRounds}, current_round = #{challengeRound}
 WHERE id = #{tournamentId} AND status = 'RUNNING'
   AND bracket_type = 'LEAGUE' AND current_round = #{expectedRound}

UPDATE game_tournament
   SET status = 'FINISHED', champion_user_id = #{championUserId},
       champion_nickname = #{championNickname},
       runner_up_user_id = #{runnerUpUserId}, runner_up_nickname = #{runnerUpNickname},
       finished_at = #{now}
 WHERE id = #{tournamentId}

UPDATE game_tournament
   SET status = 'CANCELLED', finished_at = #{now}
 WHERE id = #{tournamentId} AND status = 'INVITING'

UPDATE game_tournament
   SET deleted_at = #{now}
 WHERE id = #{tournamentId} AND deleted_at IS NULL AND status <> 'RUNNING'
